//! Parity against the independent Python oracle (spec §6.3).
//!
//! The fixtures in `tests/fixtures/oracle/` are generated by
//! `tools/oracle/umbra_oracle` and committed. Nothing in that generator imports
//! these crates, so agreement is evidence: the oracle clips each ray against the
//! voxel boxes (no traversal, no ordering) and separately quadratures the
//! analytic primitives.
//!
//! Two comparisons per ray:
//!
//! * `expected_voxel_opacity` — the rasterised field integrated per cell. This
//!   applies to every ray, curved and oblique geometry included, because both
//!   sides describe the same voxelised scene. Tolerance: 1e-4 relative.
//! * `expected_opacity` — quadrature of the analytic primitives. Only
//!   meaningful where rasterisation is exact, so each fixture carries its own
//!   tolerance; the grid-aligned box case is the tight one.
//!
//! Missing or empty fixtures are a hard failure rather than a skip: a parity
//! suite that quietly tests nothing is worse than no parity suite.

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;
use umbra_core::Grid2;
use umbra_forward::{build_system_2d, Scene2D};
use umbra_physics::{AngularBinning, Detector, Pose};

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/oracle")
}

fn field<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("fixture is missing '{key}': {value}"))
}

fn number(value: &Value) -> f64 {
    value
        .as_f64()
        .unwrap_or_else(|| panic!("expected a number, found {value}"))
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap_or_else(|| panic!("expected an array, found {value}"))
        .iter()
        .map(number)
        .collect()
}

#[test]
fn traversal_matches_the_python_oracle() {
    let dir = fixtures_dir();
    if !dir.is_dir() {
        panic!(
            "oracle fixtures are missing from {}. Regenerate them with:\n  \
             cd tools/oracle && python -m umbra_oracle fixtures --out \
             ../../crates/umbra-forward/tests/fixtures/oracle --seed 7",
            dir.display()
        );
    }

    let mut paths: Vec<PathBuf> = fs::read_dir(&dir)
        .expect("fixtures directory is readable")
        .map(|entry| entry.expect("directory entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "json"))
        .collect();
    paths.sort();
    assert!(
        !paths.is_empty(),
        "no oracle fixtures in {}; regenerate with `python -m umbra_oracle fixtures`",
        dir.display()
    );

    let mut compared = 0usize;
    let mut worst_voxel = 0.0f64;
    let mut worst_analytic = 0.0f64;

    for path in &paths {
        let text = fs::read_to_string(path).expect("fixture is readable");
        let fixture: Value = serde_json::from_str(&text)
            .unwrap_or_else(|error| panic!("{}: {error}", path.display()));

        assert_eq!(
            field(&fixture, "schema").as_str(),
            Some("umbra.oracle/1"),
            "{}",
            path.display()
        );
        let case = field(&fixture, "case").as_str().unwrap_or("<unnamed>");

        let grid_value = field(&fixture, "grid");
        let n: Vec<u32> = numbers(field(grid_value, "n"))
            .into_iter()
            .map(|value| value as u32)
            .collect();
        let origin: Vec<f32> = numbers(field(grid_value, "origin"))
            .into_iter()
            .map(|value| value as f32)
            .collect();
        let h_m = number(field(grid_value, "h_m")) as f32;
        let grid = Grid2::new([n[0], n[1]], [origin[0], origin[1]], h_m);

        let density: Vec<f32> = numbers(field(&fixture, "density"))
            .into_iter()
            .map(|value| value as f32)
            .collect();
        assert_eq!(
            density.len(),
            grid.cell_count(),
            "{}: density has {} values for {} voxels",
            path.display(),
            density.len(),
            grid.cell_count()
        );

        let rays = field(&fixture, "rays")
            .as_array()
            .expect("rays is an array");
        let expected_voxel = numbers(field(&fixture, "expected_voxel_opacity"));
        let expected_analytic = numbers(field(&fixture, "expected_opacity"));
        let voxel_tolerance = number(field(&fixture, "voxel_tolerance"));
        // `null` means the grid is too coarse for an analytic chord to be
        // reproducible (a circle at h = 0.5 m is a staircase); the measured gap
        // is still in the fixture, it is just not asserted.
        let analytic_tolerance = field(&fixture, "analytic_tolerance").as_f64();
        let analytic_floor = number(field(&fixture, "analytic_floor"));
        let max_path_m = number(field(&fixture, "max_path_m")) as f32;

        assert_eq!(
            rays.len(),
            expected_voxel.len(),
            "{}: {} rays but {} expected values",
            path.display(),
            rays.len(),
            expected_voxel.len()
        );
        assert_eq!(
            rays.len(),
            expected_analytic.len(),
            "{}: {} rays but {} analytic values",
            path.display(),
            rays.len(),
            expected_analytic.len()
        );

        // One detector per ray, its fan degenerate and centred on the ray's phi,
        // so the builder reproduces the oracle's origin and direction exactly.
        let detectors: Vec<Detector> = rays
            .iter()
            .map(|ray| {
                let phi = number(field(ray, "phi")) as f32;
                let o = numbers(field(ray, "o"));
                Detector {
                    pose: Pose {
                        position: [o[0] as f32, o[1] as f32, 0.0],
                        normal: [0.0, 1.0, 0.0],
                        up: [1.0, 0.0, 0.0],
                    },
                    area_m2: 1.0,
                    eff: 1.0,
                    binning: AngularBinning::Flat2D {
                        min: phi,
                        max: phi,
                        bins: 1,
                    },
                    sigma_ang_mrad: 0.0,
                    bg_rate_hz: 0.0,
                }
            })
            .collect();

        let scene = Scene2D {
            grid,
            detectors,
            max_path_m,
        };
        let system = build_system_2d(&scene);
        let opacity = system.opacity(&density);
        assert_eq!(opacity.len(), rays.len(), "{case}: ray count");

        for (index, ((actual, voxel), analytic)) in opacity
            .iter()
            .zip(expected_voxel.iter())
            .zip(expected_analytic.iter())
            .enumerate()
        {
            let actual = f64::from(*actual);

            let relative = (actual - voxel).abs() / voxel.abs().max(1e-9);
            worst_voxel = worst_voxel.max(relative);
            assert!(
                relative <= voxel_tolerance || (actual - voxel).abs() <= 1e-6,
                "{case} ray {index}: traversal {actual:.6e} vs oracle voxel field \
                 {voxel:.6e} g/cm2 (relative {relative:.2e}, tolerance {voxel_tolerance:.0e})"
            );

            if let Some(tolerance) = analytic_tolerance {
                if analytic.abs() > analytic_floor {
                    let analytic_relative = (actual - analytic).abs() / analytic.abs();
                    worst_analytic = worst_analytic.max(analytic_relative);
                    assert!(
                        analytic_relative <= tolerance,
                        "{case} ray {index}: traversal {actual:.6e} vs analytic chord \
                         {analytic:.6e} g/cm2 (relative {analytic_relative:.2e}, \
                         tolerance {tolerance:.0e})"
                    );
                }
            }

            compared += 1;
        }
    }

    assert!(
        compared >= 100,
        "issue #9 asks for 100+ ray/scene pairs; compared only {compared}"
    );

    println!(
        "oracle parity: {compared} ray/scene pairs across {} fixtures \
         (worst voxel {worst_voxel:.2e}, worst analytic {worst_analytic:.2e})",
        paths.len()
    );
}
